#!/usr/bin/env Rscript
# SEA4BLUE descriptive analysis; run from repository root with the existing R environment.
suppressPackageStartupMessages({library(phyloseq); library(vegan); library(ggplot2); library(dplyr)})
dir.create("data-curation/lab02", recursive = TRUE, showWarnings = FALSE)
dir.create("figures/lab02", recursive = TRUE, showWarnings = FALSE)
save_both <- function(plot, stem, width = 9, height = 6) {
  svg(paste0("figures/lab02/", stem, ".svg"), width = width, height = height); print(plot); dev.off()
  png(paste0("figures/lab02/", stem, ".png"), width = width, height = height, units = "in", res = 180); print(plot); dev.off()
}
zone_colors <- c(ANW = "#4280fc", ANC = "#ffb452", ANE = "#f7170a")
ps <- readRDS("materials/Sea4Blue/phyloseq.rds")
meta <- data.frame(sample_data(ps), check.names = FALSE); meta$sample_id <- rownames(meta)
depth <- data.frame(sample_id = sample_names(ps), reads = sample_sums(ps)) |> left_join(meta, by = "sample_id") |> mutate(sample_type = ifelse(is.na(Zone), "Control", "Environmental"))
write.csv(depth, "data-curation/lab02/sequencing_depth.csv", row.names = FALSE)
write.csv(meta, "data-curation/lab02/sample_metadata.csv", row.names = FALSE)
p_depth <- ggplot(depth, aes(x = reorder(sample_id, reads), y = reads, fill = sample_type)) + geom_col() + coord_flip() + scale_fill_manual(values = c(Control = "grey45", Environmental = "#2b8cbe")) + labs(x = NULL, y = "Reads", fill = NULL, title = "SEA4BLUE sequencing depth") + theme_bw(base_size = 13)
save_both(p_depth, "lab02_sequencing_depth", 9, 6)
ps_clean <- subset_taxa(ps, (is.na(Family) | Family != "Mitochondria") & (is.na(Order) | Order != "Chloroplast"))
ps_clean <- prune_taxa(taxa_sums(ps_clean) > 1, ps_clean)
ps_clean <- subset_samples(ps_clean, !is.na(Zone)); ps_clean <- prune_taxa(taxa_sums(ps_clean) > 0, ps_clean)
stopifnot(nsamples(ps_clean) == 15L, all(sample_sums(ps_clean) > 0))
ps_rel <- transform_sample_counts(ps_clean, function(x) x / sum(x))
alpha <- estimate_richness(ps_clean, measures = c("Observed", "Shannon")); alpha$sample_id <- rownames(alpha)
meta_clean <- data.frame(sample_data(ps_clean), check.names = FALSE); meta_clean$sample_id <- rownames(meta_clean)
alpha <- left_join(alpha, meta_clean, by = "sample_id"); write.csv(alpha, "data-curation/lab02/alpha_diversity.csv", row.names = FALSE)
p_alpha <- ggplot(alpha, aes(x = Zone, y = Shannon, color = Zone)) + geom_jitter(width = .12, height = 0, size = 3) + scale_color_manual(values = zone_colors) + labs(x = "Zone", y = "Shannon diversity", title = "Alpha diversity by SEA4BLUE zone") + theme_bw(base_size = 13) + theme(legend.position = "none")
save_both(p_alpha, "lab02_alpha_shannon", 8, 5.5)
otu_rel <- as(otu_table(ps_rel), "matrix")
if (taxa_are_rows(ps_rel)) otu_rel <- t(otu_rel)
meta_rel <- data.frame(sample_data(ps_rel), check.names = FALSE)[rownames(otu_rel), , drop = FALSE]
bray <- vegdist(otu_rel, method = "bray"); pcoa <- cmdscale(bray, k = 2, eig = TRUE, add = TRUE)
pcoa_df <- data.frame(sample_id = rownames(pcoa$points), PCoA1 = pcoa$points[, 1], PCoA2 = pcoa$points[, 2], meta_rel)
write.csv(pcoa_df, "data-curation/lab02/pcoa_bray_coordinates.csv", row.names = FALSE)
axis_pct <- round(100 * pcoa$eig[1:2] / sum(pcoa$eig[pcoa$eig > 0]), 1)
p_pcoa <- ggplot(pcoa_df, aes(PCoA1, PCoA2, color = Zone, label = SampleName)) + geom_point(size = 3) + geom_text(nudge_y = .012, size = 3, show.legend = FALSE) + scale_color_manual(values = zone_colors) + labs(x = paste0("PCoA 1 (", axis_pct[1], "%)"), y = paste0("PCoA 2 (", axis_pct[2], "%)"), title = "Bray–Curtis PCoA") + theme_bw(base_size = 13)
save_both(p_pcoa, "lab02_bray_pcoa", 8, 6)
set.seed(42); perm <- adonis2(bray ~ Zone, data = meta_rel, permutations = 999)
disp <- betadisper(bray, group = meta_rel$Zone); disp_aov <- anova(disp); set.seed(42); disp_perm <- permutest(disp, permutations = 999)
stat <- data.frame(metric = c("original_samples", "original_taxa", "ecological_samples_after_filter", "taxa_after_filter", "PERMANOVA_R2", "PERMANOVA_p", "dispersion_ANOVA_p", "dispersion_permutation_p"), value = c(nsamples(ps), ntaxa(ps), nsamples(ps_clean), ntaxa(ps_clean), perm$R2[1], perm$`Pr(>F)`[1], disp_aov$`Pr(>F)`[1], disp_perm$tab$`Pr(>F)`[1]))
write.csv(stat, "data-curation/lab02/analysis_summary.csv", row.names = FALSE)
ps_genus <- tax_glom(ps_rel, taxrank = "Genus", NArm = FALSE); genus <- psmelt(ps_genus)
top <- genus |> filter(!is.na(Genus)) |> group_by(Genus) |> summarise(total = sum(Abundance), .groups = "drop") |> arrange(desc(total)) |> slice_head(n = 12) |> pull(Genus)
comp <- genus |> mutate(genus_plot = ifelse(is.na(Genus) | !Genus %in% top, "Other", as.character(Genus))) |> group_by(Sample, Zone, genus_plot) |> summarise(relative_abundance = sum(Abundance), .groups = "drop")
write.csv(comp, "data-curation/lab02/genus_composition_top12.csv", row.names = FALSE)
p_comp <- ggplot(comp, aes(Sample, relative_abundance, fill = genus_plot)) + geom_col(width = .85) + facet_grid(~Zone, scales = "free_x", space = "free_x") + scale_y_continuous(labels = function(x) paste0(round(100*x), "%")) + labs(x = NULL, y = "Relative abundance", fill = "Genus", title = "Top 12 genera; other taxa aggregated") + theme_bw(base_size = 11) + theme(axis.text.x = element_text(angle = 90, hjust = 1))
save_both(p_comp, "lab02_genus_composition", 12, 6)
cat("SEA4BLUE descriptive outputs created.\n")
